package mx.jorge.despierta;
import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.*;import android.media.AudioAttributes;import android.view.*;import android.widget.*;
public final class AudioOutputSettings {
 public static int usage(Context c){return AudioSafety.strict(c)?AudioAttributes.USAGE_MEDIA:c.getSharedPreferences("appearance",0).getBoolean("mediaAudio",false)?AudioAttributes.USAGE_MEDIA:AudioAttributes.USAGE_ALARM;}
 static String name(Context c){return usage(c)==AudioAttributes.USAGE_MEDIA?"Multimedia":"Alarma";}
 static int dp(Context c,int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
 static Button button(Context c,String text,boolean selected){Button b=new Button(c);b.setAllCaps(false);b.setBackgroundTintList(null);b.setText(text);b.setTextSize(16);b.setTextColor(VibrationEditor.color(c,selected?"onAccent":"fg",selected?0xff10241e:Color.WHITE));GradientDrawable bg=new GradientDrawable();bg.setColor(VibrationEditor.color(c,selected?"accent":"card",selected?0xffb9ef96:0xff294237));bg.setCornerRadius(dp(c,20));b.setBackground(bg);b.setPadding(dp(c,12),dp(c,8),dp(c,12),dp(c,8));return b;}
 public static void attach(Context c,LinearLayout page){Button entry=button(c,"Medio de reproducción · "+name(c)+"  ›",false);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(c,58));lp.setMargins(0,dp(c,6),0,dp(c,6));page.addView(entry,lp);entry.setOnClickListener(v->show(c,entry));}
 static void show(Context c,Button entry){Dialog dialog=new Dialog(c);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout panel=new LinearLayout(c);panel.setOrientation(1);panel.setPadding(dp(c,22),dp(c,18),dp(c,22),dp(c,22));GradientDrawable bg=new GradientDrawable();bg.setColor(VibrationEditor.color(c,"surface",0xff17392e));bg.setCornerRadius(dp(c,26));panel.setBackground(bg);TextView title=new TextView(c);title.setText("Medio de reproducción");title.setTextSize(23);title.setTextColor(VibrationEditor.color(c,"fg",Color.WHITE));panel.addView(title);TextView info=new TextView(c);info.setText("Multimedia: usa el volumen y la salida de música del teléfono, por ejemplo tus audífonos. Activa Solo audífonos para silenciar el audio y usar vibración cuando no haya una salida privada.\n\nAlarma: usa el volumen de alarmas y la salida que determine Android.\n\nSe aplica a todas las alarmas con sonido. Pruébalo con tus audífonos antes del viaje.");info.setTextSize(15);info.setTextColor(VibrationEditor.color(c,"fg",Color.WHITE));info.setPadding(0,dp(c,14),0,dp(c,12));panel.addView(info);
 for(int i=0;i<2;i++){final boolean media=i==0;boolean selected=(usage(c)==AudioAttributes.USAGE_MEDIA)==media;Button option=button(c,(media?"Multimedia":"Alarma")+(selected?"  ✓":""),selected);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(c,50));lp.topMargin=dp(c,8);panel.addView(option,lp);option.setOnClickListener(v->{c.getSharedPreferences("appearance",0).edit().putBoolean("mediaAudio",media).putBoolean("onlyHeadphones",media&&AudioSafety.strict(c)).apply();entry.setText("Medio de reproducción · "+name(c)+"  ›");dialog.dismiss();});}
 Switch privacy=new Switch(c);privacy.setText("Solo audífonos · sin ellos, vibrar");privacy.setTextColor(Color.WHITE);privacy.setChecked(AudioSafety.strict(c));privacy.setOnCheckedChangeListener((v,on)->{c.getSharedPreferences("appearance",0).edit().putBoolean("onlyHeadphones",on).putBoolean("mediaAudio",on||usage(c)==AudioAttributes.USAGE_MEDIA).apply();entry.setText("Medio de reproducción · "+name(c)+"  ›");});panel.addView(privacy);
 ScrollView scroll=new ScrollView(c);scroll.addView(panel);dialog.setContentView(scroll);dialog.show();Window window=dialog.getWindow();window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));window.setGravity(Gravity.BOTTOM);panel.measure(View.MeasureSpec.makeMeasureSpec(c.getResources().getDisplayMetrics().widthPixels,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));window.setLayout(-1,Math.min(panel.getMeasuredHeight(),(int)(c.getResources().getDisplayMetrics().heightPixels*.82)));}
}
